// src/features/slices/authSlice.js
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  user: null,
  token: null,
  isAuthenticated: false,
  loading: false,
  error: null,
};

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    // Set credentials (used for initial auth restore and login)
    setCredentials: (state, action) => {
      const { user, token } = action.payload;
      state.user = user;
      state.token = token;
      state.isAuthenticated = !!token && !!user;
      state.loading = false;
      state.error = null;

      // Persist to localStorage
      if (token && user) {
        localStorage.setItem('auth', JSON.stringify({ user, token }));
      }
    },

    // Login success (alternative to setCredentials)
    loginSuccess: (state, action) => {
      const { user, token } = action.payload;
      state.user = user;
      state.token = token;
      state.isAuthenticated = true;
      state.loading = false;
      state.error = null;
      localStorage.setItem('auth', JSON.stringify({ user, token }));
    },

    // Login user action
    loginUser: (state) => {
      state.loading = true;
      state.error = null;
    },

    // Logout
    logout: (state) => {
      state.user = null;
      state.token = null;
      state.isAuthenticated = false;
      state.loading = false;
      state.error = null;
      localStorage.removeItem('auth');
    },

    // Logout user (alias for logout)
    logoutUser: (state) => {
      state.user = null;
      state.token = null;
      state.isAuthenticated = false;
      state.loading = false;
      state.error = null;
      localStorage.removeItem('auth');
    },

    // Set loading state
    setLoading: (state, action) => {
      state.loading = action.payload;
    },

    // Update user data
    updateUser: (state, action) => {
      state.user = { ...state.user, ...action.payload };
      if (state.token && state.user) {
        localStorage.setItem('auth', JSON.stringify({ user: state.user, token: state.token }));
      }
    },

    // Clear auth error
    clearAuthError: (state) => {
      state.error = null;
    },
  },
});

// Selectors
export const selectUser = (state) => state.auth.user;
export const selectToken = (state) => state.auth.token;
export const selectIsAuthenticated = (state) => state.auth.isAuthenticated;
export const selectAuthLoading = (state) => state.auth.loading;
export const selectAuthError = (state) => state.auth.error;
export const selectUserRole = (state) => state.auth.user?.role;

// Export actions
export const {
  setCredentials,
  loginSuccess,
  loginUser,
  logout,
  logoutUser,
  setLoading,
  updateUser,
  clearAuthError,
} = authSlice.actions;

export default authSlice.reducer;